using System.Text;
using UnityEngine;
using UnityEngine.UI;

public static class SceneDump
{
    static StringBuilder sb;

    public static string Run()
    {
        sb = new StringBuilder();
        var canvas = GameObject.Find("MainMenuCanvas");
        if (canvas == null) sb.AppendLine("NO CANVAS");
        else Walk(canvas.transform, "");
        return sb.ToString();
    }

    static void Walk(Transform t, string indent)
    {
        var rt = t as RectTransform;
        string info = "";
        if (rt != null)
        {
            info = string.Format(" pos={0:F0} size={1:F0} anchor={2:F2}->{3:F2} pivot={4:F2} rot={5:F1} scale={6:F2}",
                rt.anchoredPosition, rt.sizeDelta, rt.anchorMin, rt.anchorMax, rt.pivot, rt.localEulerAngles.z, rt.localScale.x);
            var img = t.GetComponent<Graphic>();
            if (img != null)
            {
                info += " color=#" + ColorUtility.ToHtmlStringRGBA(img.color) + " ray=" + img.raycastTarget;
                var shape = t.GetComponent<AfoShapeImage>();
                if (shape != null) info += " shape=" + shape.shape + " cut=" + shape.cornerCut;
                var txt = img as Text;
                if (txt != null) info += string.Format(" text=\"{0}\" font={1} size={2} style={3} align={4}", txt.text, txt.font != null ? txt.font.name : "null", txt.fontSize, txt.fontStyle, txt.alignment);
                foreach (var e in t.GetComponents<BaseMeshEffect>()) info += " fx=" + e.GetType().Name;
            }
            var cg = t.GetComponent<CanvasGroup>();
            if (cg != null) info += " alpha=" + cg.alpha;
        }
        sb.AppendLine(indent + t.name + info);
        for (int i = 0; i < t.childCount; i++) Walk(t.GetChild(i), indent + "  ");
    }
}
